// === Tab: Circles ===
var spacing = 16;
var meanDiam = 8;
function setup(){
  createCanvas(800, 600);
  ellipseMode(CENTER);
  noStroke();
  fill(255);
window.simulatedMouseX = width/2;
window.simulatedMouseY = height/2;
}
function draw(){
  background(0);
  let flipFlop = 1;
  for(let y=spacing/2;y<width;y+=spacing){
    flipFlop = (flipFlop+1)%2;
    for(x=spacing*(1-flipFlop*0.5);x<width;x+=spacing){
      let dx = x-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
      let dy = y-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
      let radius = mag(dy,dx);
      let angle = atan2(dy,dx)-frameCount*TWO_PI/40;
      let variation = meanDiam/2*cos(radius*TWO_PI/spacing/4+angle);
      let varried = meanDiam*1.25+variation;
      ellipse(x,y,varried,varried);
    }
  }
}
